function lowestCommonAncestor(root, p, q) {
  const path = (x) => { const a = []; let n = root; while (n) { a.push(n.val); if (n.val === x) break; n = x < n.val ? n.left : n.right; } return a; };
  const A = path(p), B = path(q); let i = 0;
  while (i < A.length && i < B.length && A[i] === B[i]) i++;
  return A[i - 1];
